package com.vms.vendorcontractmanagement.controller; import com.vms.vendorcontractmanagement.dto.VendorDtos.*; import com.vms.vendorcontractmanagement.service.*; import jakarta.validation.*; import lombok.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/vendors") @RequiredArgsConstructor public class VendorController {final VendorService service; @GetMapping public Page<Response> list(@RequestParam(required=false) String search,@RequestParam(required=false) String category,@RequestParam(required=false) String status,Pageable pageable){return service.list(search,category,status,pageable);}@GetMapping("/{id}") public Response get(@PathVariable Long id){return service.get(id);}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") @ResponseStatus(HttpStatus.CREATED) public Response create(@Valid @RequestBody Request r){return service.create(r);}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public Response update(@PathVariable Long id,@Valid @RequestBody Request r){return service.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}@PutMapping("/{id}/status") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public Response status(@PathVariable Long id,@RequestParam String status){return service.status(id,status);} }
